import React, { useEffect, useState } from "react";
import axios from "axios";
import { toast, ToastContainer } from 'react-toastify';
import { Container, Box, Button, Grid2 } from "@mui/material";
import { UrlContext } from "./UrlContext";
import { getToken } from "../utils/GenUtils";
import UrlList from "./UrlList";
import FormDialog from "./FormDialog";
import { DELETE_URL_ROUTE, INSERT_URL_ROUTE, UPDATE_URL_ROUTE } from "../config/routeConfig";
import "react-toastify/dist/ReactToastify.css";
import { useNavigate } from "react-router-dom";

export default function UrlPage1() {
  const urlConsumer = React.useContext(UrlContext);
  const navigate = useNavigate();
  const [modalOpen, setModalOpen] = useState(false);
  const [urlId, setUrlId] = useState("");
  const [originalUrl, setOriginalUrl] = useState("");
  const [expirationDate, setExpirationDate] = useState("");
  const [urlName, setUrlName] = useState("");
  const [submit, setSubmit] = useState(false);
  const [error, setError] = useState(true);
  const [mode, setMode] = useState("add");
  
  // const floatingButtonStyle = {
  //   margin: 0,
  //   top: "auto",
  //   right: 20,
  //   bottom: 20,
  //   left: "auto",
  //   position: "fixed",
  // };

  useEffect(() => {
    urlConsumer.initUrlList();
    if (urlConsumer.error) {
      navigate("/login");
    }
  }, [urlConsumer.error, submit, navigate]);

  const handleModalClose = (e, reason) => {
    if (!["backdropClick"].includes(reason)) {
      setModalOpen(false);
    }
  };

  const handleChange = (e, error = '', type) => {
    console.log("Event");
    console.log(e, error = '', type);
    if (type && type === 'expirationDate') {
      // let value = e;
      // value = value ? new Date(value).toISOString() : new Date().toISOString()
      setExpirationDate(new Date(e).toISOString());
    } else if (e.target.name === 'originalUrl') {
      setOriginalUrl(e.target.value);
    } else if (e.target.name === 'urlName') {
      setUrlName(e.target.value);
    }
  }

  const closeWithoutSaving = () => {
    setModalOpen(false);
    setOriginalUrl('')
    setUrlName('')
  }

  const handleModalOpen = (e) => {
    setMode("add");
    setModalOpen(true);
    setOriginalUrl('')
    setUrlName('')
    setExpirationDate(new Date().toISOString())
  };

  const updateModalOpenClose = (e, urlData) => {
    console.log("urlData", urlData);
    console.log(e);
    setMode("update")
    setUrlId(urlData._id);
    setUrlName(urlData.urlName);
    setOriginalUrl(urlData.originalUrl);
    setExpirationDate(new Date(urlData.expirationDate));
    setModalOpen(true)
  }

  const handleDeleteUrl = (id) => {
    console.log("id", id);
    axios.delete(`${DELETE_URL_ROUTE}/${id}`, {
      headers: {
        Authorization: getToken(),
      },
    })
    .then((res) => {
      console.log("Response::");
      console.log(res);
      // callback(res);
      let { data } = res;
      toast(data.message, { autoClose: 2000 });
      setModalOpen(false);
      // setUrlId("");
      setSubmit(prevState => !prevState.submit)
    })
    .catch((err) => {
      console.log("Error::handleDeleteUrl");
      console.log(err);
      let {
        response: { data },
      } = err;
      toast(data.message, { autoClose: 2000 });
    });
  }

  const handleSubmit = () => {
    if (!originalUrl || !expirationDate || !urlName) {
      alert("All fields are required!");
      return;
    }
    setError(false);
    console.log("originalUrl, expirationDate, urlName");
    console.log(originalUrl, expirationDate, urlName);

    let reqObj = {};
    if (mode === "add") {
      reqObj = { originalUrl, urlName, expirationDate }
    } else {
      reqObj["urlId"] = urlId;
      if (urlName) reqObj["urlName"] = urlName;
      if (expirationDate) reqObj["expirationDate"] = expirationDate;
    }
    axios({
      url: mode === "add" ? INSERT_URL_ROUTE : UPDATE_URL_ROUTE,
      method: mode === "add" ? "post" : "put",
      headers: {
        Authorization: getToken(),
      },
      data: reqObj,
    })
      .then((res) => {
        console.log("Response::");
        console.log(res);
        // callback(res);
        let { data } = res;
        toast(data.message, { autoClose: 2000 });
        setModalOpen(false);
        setUrlId("");
        setOriginalUrl("");
        setUrlName("");
        setExpirationDate("")
        setSubmit(prevState => !prevState.submit)
      })
      .catch((err) => {
        console.log("Error::addUrl");
        console.log(err);
        let {
          response: { data },
        } = err;
        let message = data.error ? data.error[0].message : data.message;
        toast(message, { autoClose: 2000 });
      });
  };

  return (
    <React.Fragment>
      <Grid2 container spacing={2} direction="column" padding={8}>
        {/* Add URL Button (Positioned before the table) */}
        <Grid2 item xs={12} sm={6} md={4}>
          <Box display="flex" justifyContent="flex-end" sx={{ mb: 2 }}>
            <Button variant="contained" color="primary" onClick={handleModalOpen}>Add URL</Button>
          </Box>
        </Grid2>
        <Grid2 item xs={12} sm={6} md={4}>
          <UrlList updateModalOpenClose={updateModalOpenClose} handleDeleteUrl={handleDeleteUrl} /> 
        </Grid2>
        <ToastContainer style={{}} />
      </Grid2>
      <FormDialog
        originalUrl={originalUrl}
        urlName={urlName}
        expirationDate={expirationDate}
        handleChange={handleChange}
        setOriginalUrl={setOriginalUrl}
        setUrlName={setUrlName}
        setExpirationDate={setExpirationDate}
        onSubmit={handleSubmit}
        modalOpen={modalOpen}
        handleModalClose={handleModalClose}
        closeWithoutSaving={closeWithoutSaving}
        mode={mode}
      />
    </React.Fragment>
  );
}
